import{_ as c,C as i,o as l,c as n,ak as r,E as o,j as d,a}from"./chunks/framework.DxrHb2fb.js";const x=JSON.parse('{"title":"Rating 评分","description":"","frontmatter":{},"headers":[],"relativePath":"components/rating.md","filePath":"components/rating.md","lastUpdated":1790400917000}'),h={name:"components/rating.md"};function s(b,t,u,g,p,m){const e=i("XhDemo");return l(),n("div",null,[t[0]||(t[0]=r('<h1 id="rating-评分" tabindex="-1">Rating 评分 <a class="header-anchor" href="#rating-评分" aria-label="Permalink to &quot;Rating 评分&quot;">​</a></h1><p>用一排图案表示一个离散的分值。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/rating" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/rating.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/rating" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/rating" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/rating.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>不传 value 即为非受控，组件自行维护评分；default-value 只决定初始档位</p>',5)),o(e,{src:"rating/01-basic"}),t[1]||(t[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;rating&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <strong><code>control</code></strong> · <code>value-text</code> · <strong><code>item</code></strong> · <code>hidden-input</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="半星与悬停预览" tabindex="-1">半星与悬停预览 <a class="header-anchor" href="#半星与悬停预览" aria-label="Permalink to &quot;半星与悬停预览&quot;">​</a></h3><p>allow-half 使落点分左右半边；划过只发 hover-change，评分要点击后才改变</p>',6)),o(e,{src:"rating/02-half"}),t[2]||(t[2]=d("h3",{id:"自定义档数",tabindex:"-1"},[a("自定义档数 "),d("a",{class:"header-anchor",href:"#自定义档数","aria-label":'Permalink to "自定义档数"'},"​")],-1)),t[3]||(t[3]=d("p",null,"count 决定几颗星，星星按 1..count 逐颗写出",-1)),o(e,{src:"rating/03-count"}),t[4]||(t[4]=d("h3",{id:"只读与禁用",tabindex:"-1"},[a("只读与禁用 "),d("a",{class:"header-anchor",href:"#只读与禁用","aria-label":'Permalink to "只读与禁用"'},"​")],-1)),t[5]||(t[5]=d("p",null,"read-only 仍进入 Tab 序列、读屏可朗读但不可修改；disabled 整条退出 Tab 序列",-1)),o(e,{src:"rating/04-readonly-disabled"}),t[6]||(t[6]=d("h3",{id:"颜色",tabindex:"-1"},[a("颜色 "),d("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),t[7]||(t[7]=d("p",null,"tone 决定点亮的星使用哪族颜色，不写时沿用警示色",-1)),o(e,{src:"rating/05-tone"}),t[8]||(t[8]=d("h3",{id:"尺寸",tabindex:"-1"},[a("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[9]||(t[9]=d("p",null,"size 改变星的大小与间距，不写即默认中档",-1)),o(e,{src:"rating/06-size"}),t[10]||(t[10]=d("h3",{id:"自定义图标",tabindex:"-1"},[a("自定义图标 "),d("a",{class:"header-anchor",href:"#自定义图标","aria-label":'Permalink to "自定义图标"'},"​")],-1)),t[11]||(t[11]=d("p",null,"条目可使用首方图标，也可留空使用皮肤默认星形",-1)),o(e,{src:"rating/07-icon"}),t[12]||(t[12]=d("h3",{id:"自定义颜色",tabindex:"-1"},[a("自定义颜色 "),d("a",{class:"header-anchor",href:"#自定义颜色","aria-label":'Permalink to "自定义颜色"'},"​")],-1)),t[13]||(t[13]=d("p",null,"点亮色与未点亮色各是一个组件令牌，写在行内即可脱离语气档",-1)),o(e,{src:"rating/08-color"}),t[14]||(t[14]=d("h3",{id:"再点一次清空",tabindex:"-1"},[a("再点一次清空 "),d("a",{class:"header-anchor",href:"#再点一次清空","aria-label":'Permalink to "再点一次清空"'},"​")],-1)),t[15]||(t[15]=d("p",null,"allowClear 默认开启：点击当前档位清回未评分，键盘在最低档再向下一步同样清零；设为 false 关闭",-1)),o(e,{src:"rating/09-clearable"}),t[16]||(t[16]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>收集或展示满意度、星级等小范围的主观分值。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>分值范围大（0 到 100）时，使用<a href="./slider">滑块</a>或<a href="./number-field">数字字段</a>。</li><li>只展示一个数值时，使用<a href="./statistic">统计数值</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>allowHalf</code> 支持半档，<code>allowClear</code> 允许再次点击清空。</li><li>悬停预览与实际值分开，<code>onHoverChange</code> 单独回调。</li><li>条目留空时使用库内置的星形图标；也可传入自定义图标与颜色。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>外层放<a href="./field">表单字段</a>；只读展示时与<a href="./statistic">统计数值</a>并列。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>档数固定为五档，更多档用户无法分辨差别。</li><li>只读展示时同时写出数值（4.2 / 5），图案本身读不出精确值。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用它展示进度，那是<a href="./progress">进度条</a>。</li><li>不允许清空却也没有默认值，用户误点后无法恢复。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-rating&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhRatingControl</code> <code>XhRatingHiddenInput</code> <code>XhRatingItem</code> <code>XhRatingLabel</code> <code>XhRatingRoot</code> <code>XhRatingValueText</code></td></tr><tr><td>组合式函数</td><td><code>useRating</code></td></tr><tr><td>状态机</td><td><code>ratingMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/rating.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>受控评分。提供即受控：内部不再自行落值，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>number</code></td><td></td><td>非受控初值，默认 0（尚未评分）。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>星星颗数，默认 5。</td></tr><tr><td><code>allowHalf</code></td><td><code>boolean</code></td><td></td><td>允许半颗星：档位从 1 变为 0.5。</td></tr><tr><td><code>allowClear</code></td><td><code>boolean</code></td><td></td><td>再次点击当前档位即清零，键盘在最低档再向下一步同样清零；默认开启。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>完全不可交互：退出 Tab 序列，指针与键盘都不响应。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：仍可聚焦、仍能被读屏朗读，但不可修改，也不提供悬停预览。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；提供后表单影子才带 name 并参与提交。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 &#39;ltr&#39;。只改写左右方向键与指针落在哪半边的语义。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定使用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;RatingTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: RatingValueChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onHoverChange</code></td><td><code>(details: RatingHoverChangeDetails) =&gt; void</code></td><td></td><td>悬停预览变化；指针离开时带 null。它不代表值已变化。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>RatingValueChangeDetails</code></td><td>评分变化；detail 为 <code>{ value: number }</code></td></tr><tr><td><code>hover-change</code></td><td><code>RatingHoverChangeDetails</code></td><td>悬停预览变化；detail 为 <code>{ value: number | null }</code>，指针离开时带 null</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhRatingItem</code></td><td><code>default</code></td><td><code>RatingItemSlotProps</code></td><td></td></tr><tr><td><code>XhRatingRoot</code></td><td><code>default</code></td><td><code>RatingRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhRatingItem</code></td><td><code>value</code></td><td><code>number | string</code></td><td>是</td><td>星序号，兼收字符串；向下传递前统一归为数字。</td></tr><tr><td><code>XhRatingItem</code></td><td><code>children</code></td><td><code>SlotChildren&lt;RatingItemSlotProps&gt;</code></td><td></td><td></td></tr><tr><td><code>XhRatingRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;RatingRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>VALUE.STEP</code> · <code>VALUE.TO_MIN</code> · <code>VALUE.TO_MAX</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>ITEM.HOVER</code> · <code>HOVER.CLEAR</code> · <code>CONTROL.BLUR</code> · <code>FORM.RESET</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>canInteract</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td>已归一化的评分：非法与越界的宿主输入在这里被夹回。</td></tr><tr><td><code>hoveredValue</code></td><td><code>number | null</code></td><td>指针预览值；没有预览（或不可交互）时为 null。</td></tr><tr><td><code>highlightedValue</code></td><td><code>number</code></td><td>当前应点亮到的位置：有预览时是预览值，否则是评分。样式与 data-highlighted 使用的都是它。</td></tr><tr><td><code>valueText</code></td><td><code>string</code></td><td>分值文本：当前应点亮到的数值，指针预览期间跟随预览值。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>尚未评分（value 为 0）。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>items</code></td><td><code>readonly number[]</code></td><td>1..count 的序号表，作者直接遍历它渲染星星。</td></tr><tr><td><code>getItemState</code></td><td><code>(props: RatingItemProps) =&gt; RatingItemState</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: number) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getValueTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>分值文本：写在 root 中、control 的兄弟；aria-hidden，读屏使用星星自身的可及名。</td></tr><tr><td><code>getItemProps</code></td><td><code>(props: RatingItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单出口：一份视觉隐藏的原生输入，随表单提交当前评分。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the control</td><td>整条评分带只占一个 Tab 位：焦点进入锚点星，无锚点时进入容器并由它转移到首颗</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowUp</code></td><td>focus in control, not disabled/readOnly</td><td>加一档（allowHalf 时半颗），到顶停在 count；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowDown</code></td><td>focus in control, not disabled/readOnly</td><td>减一档，到底停在最小档，不会退回&quot;还没评&quot;；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Home</code></td><td>focus in control, not disabled/readOnly</td><td>取最小档（allowHalf 时是半颗，否则一颗）</td></tr><tr><td><code>End</code></td><td>focus in control, not disabled/readOnly</td><td>取满分（count）</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>control</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>control</code></td><td><code>aria-orientation</code></td><td>&#39;horizontal&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>control</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>value-text</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-label</code></td><td>itemLabel?.(item.value, count)</td></tr><tr><td><code>item</code></td><td><code>aria-posinset</code></td><td>item.value</td></tr><tr><td><code>item</code></td><td><code>aria-setsize</code></td><td>ratingMax(prop(&#39;count&#39;))</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/rating.css</code> 使用 <code>[data-scope=&quot;rating&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>value-text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>value-text</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>value-text</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-half</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-highlighted</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-profile</code></td><td>&#39;icon&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-rating-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>rating 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-rating-item-bg-pressed</code></td><td><code>item</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-bg-subtle-hover</code></td><td>rating 的 item 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-rating-item-fg</code></td><td><code>item</code></td><td><code>background-color</code><br><code>background-image</code><br><code>color</code></td><td><code>default</code><br><code>dir(rtl)</code><br><code>disabled</code><br><code>empty</code><br><code>focus-visible</code><br><code>half</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not(:empty)</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-fg-subtle</code></td><td>rating 的 item 部件 background-color、background-image、color 覆盖槽。</td></tr><tr><td><code>--xh-rating-item-fg-highlighted</code></td><td><code>item</code></td><td><code>background-color</code><br><code>background-image</code><br><code>color</code></td><td><code>@media print</code><br><code>dir(rtl)</code><br><code>disabled</code><br><code>empty</code><br><code>focus-visible</code><br><code>half</code><br><code>highlighted</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not(:empty)</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_rating-accent</code></td><td>rating 的 item 部件 background-color、background-image、color 覆盖槽。</td></tr><tr><td><code>--xh-rating-item-font-size</code></td><td><code>item</code><br><code>root</code></td><td><code>--xh-icon-size</code><br><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_rating-item-size</code></td><td>rating 的 item、root 部件 --xh-icon-size、font-size 覆盖槽。</td></tr><tr><td><code>--xh-rating-item-gap</code></td><td><code>control</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_rating-item-gap</code></td><td>rating 的 control 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-rating-item-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>rating 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-rating-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>rating 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-rating-label-fg-disabled</code></td><td><code>label</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>rating 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-rating-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>rating 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-rating-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>rating 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-rating-value-text-fg</code></td><td><code>value-text</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>rating 的 value-text 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-rating-value-text-fg-disabled</code></td><td><code>value-text</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>rating 的 value-text 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-rating-value-text-font-size</code></td><td><code>value-text</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_rating-font-size</code></td><td>rating 的 value-text 部件 font-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：按压 · 状态 · 切换（见<a href="./../design/motion#角色">动效规范</a>）。</p><p><code>clip-path</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><p>皮肤另按输入能力分档：<code>pointer: coarse</code>：同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p>',62))])}const q=c(h,[["render",s]]);export{x as __pageData,q as default};
